const app = document.querySelector('#app');
let state = { user: null, csrf: null, view: 'dashboard', locations: [], products: [], toastTimer: null };
const esc = (v='') => String(v ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const money = v => new Intl.NumberFormat('en-ET',{style:'currency',currency:'ETB',maximumFractionDigits:2}).format(Number(v||0));
const qty = v => new Intl.NumberFormat('en-US',{maximumFractionDigits:3}).format(Number(v||0));
const date = v => v ? new Date(v).toLocaleString() : '—';
const titleCase = s => String(s||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());

async function api(path, options={}) {
  const headers = {'Accept':'application/json', ...(options.headers||{})};
  if (options.body !== undefined) headers['Content-Type']='application/json';
  if (options.method && !['GET','HEAD'].includes(options.method.toUpperCase()) && !['/api/auth/login','/api/setup','/api/auth/logout'].includes(path)) headers['X-CSRF-Token']=state.csrf || '';
  const response = await fetch(path,{...options,headers,credentials:'same-origin'});
  if (response.status===204) return null;
  const payload = await response.json().catch(()=>({error:'Unexpected server response.'}));
  if (!response.ok) throw new Error(payload.error || `Request failed (${response.status})`);
  return payload;
}
function toast(message, isError=false) {
  let el=document.querySelector('.toast'); if(!el){el=document.createElement('div');el.className='toast';document.body.appendChild(el);}
  el.textContent=message;el.className=`toast${isError?' error':''}`;clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.remove(),3800);
}
function authScreen(setup=false) {
  app.innerHTML=`<div class="auth-wrap"><section class="auth-visual"><div class="brand"><div class="brand-mark">S</div><div><strong>STOCKLAND</strong><small>GLOBAL BRANDS · LOCAL ACCESS</small></div></div><div><div class="eyebrow" style="color:#a9c0b2">OPERATIONS PLATFORM</div><h1>One clear view of every stock movement.</h1><p>Garment product master, branch inventory, retail POS and controlled POS imports in one operational workspace.</p></div><div class="subtle" style="color:#9eb1a5">STOCKLAND ETHIOPIA · LOCAL DEVELOPMENT EDITION</div></section><section class="auth-panel"><div class="auth-card"><div class="brand-mark">S</div><div class="eyebrow" style="margin-top:18px">${setup?'FIRST-TIME CONFIGURATION':'SECURE WORKSPACE'}</div><h2>${setup?'Create the owner account':'Welcome back'}</h2><p class="subtle">${setup?'This creates the first platform owner and initializes the five Stockland locations.':'Sign in with your Stockland ERP user account.'}</p><form id="auth-form" class="grid" style="gap:13px;margin-top:22px">${setup?`<div class="field"><label>Owner name</label><input name="fullName" required maxlength="120" placeholder="Full name"></div>`:''}<div class="field"><label>Email address</label><input name="email" type="email" required autocomplete="username" placeholder="name@company.com"></div><div class="field"><label>Password</label><input name="password" type="password" required minlength="12" maxlength="128" autocomplete="${setup?'new-password':'current-password'}" placeholder="At least 12 characters"></div>${setup?'<p class="hint">Use a unique password of at least 12 characters. It will not be displayed again.</p>':''}<button class="btn" type="submit">${setup?'Initialize Stockland ERP':'Sign in'}</button><div id="auth-error" class="hint" role="alert"></div></form></div></section></div>`;
  document.querySelector('#auth-form').addEventListener('submit',async e=>{
    e.preventDefault();const fd=new FormData(e.currentTarget);const data=Object.fromEntries(fd.entries());
    const btn=e.currentTarget.querySelector('button');btn.disabled=true;btn.textContent='Please wait…';
    try{const result=await api(setup?'/api/setup':'/api/auth/login',{method:'POST',body:JSON.stringify(data)});state.user=result.user;state.csrf=result.csrfToken;await loadWorkspace();}
    catch(err){document.querySelector('#auth-error').textContent=err.message;btn.disabled=false;btn.textContent=setup?'Initialize Stockland ERP':'Sign in';}
  });
}
const navItems=[
  ['dashboard','Overview','◫'],['products','Product master','▦'],['suppliers','Suppliers','♧'],['customers','Customers & resellers','♙'],
  ['procurement','Procurement & receiving','⇩'],['inventory','Inventory & transfers','▤'],['requisitions','Branch requisitions','⇄'],['reservations','Reservations','◷'],
  ['counts','Physical stock count','▣'],['pos','Retail point of sale','▣'],['returns','Returns & damage','↶'],['wholesale','Wholesale orders','▤'],
  ['imports','POS imports & release','⇧'],['finance','Finance & accounting','₿'],['hr','HR & payroll','♙'],['closing','Daily closing','◴'],
  ['reports','Reports','▥'],['users','Users & access','♙'],['audit','Audit trail','◷']
];
function shell() {
  const user=state.user;
  const items=navItems.filter(([id])=>{
    const role=user.role;
    if(id==='users') return ['owner','admin'].includes(role);
    if(id==='audit') return ['owner','admin','auditor'].includes(role);
    if(id==='reports'||id==='finance') return ['owner','admin','accountant','auditor'].includes(role) || (id==='reports'&&role==='branch_manager');
    if(id==='hr') return ['owner','admin','accountant','auditor'].includes(role);
    if(id==='suppliers'||id==='procurement') return ['owner','admin','warehouse_manager','accountant'].includes(role);
    if(id==='customers') return ['owner','admin','accountant','branch_manager','cashier'].includes(role);
    if(id==='wholesale') return ['owner','admin','branch_manager','cashier'].includes(role);
    if(id==='closing') return ['owner','admin','branch_manager'].includes(role);
    if(['requisitions','reservations','counts','returns','inventory'].includes(id)) return ['owner','admin','branch_manager','warehouse_manager','cashier'].includes(role);
    return true;
  });
  app.innerHTML=`<div class="layout"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">S</div><div><strong>STOCKLAND</strong><small>ERP WORKSPACE</small></div></div><div><div class="nav-label">OPERATIONS</div><nav class="nav">${items.map(([id,label,ico])=>`<button data-view="${id}" class="${state.view===id?'active':''}"><span class="nav-ico">${ico}</span>${label}</button>`).join('')}</nav></div><div class="side-bottom"><div class="side-user">${esc(user.fullName)}</div><div class="side-role">${esc(titleCase(user.role))} · ${esc(user.locationName||'All locations')}</div><button class="logout" id="logout">Sign out ↗</button></div></aside><main><header class="topbar"><div class="row"><button class="btn ghost mobile-menu" id="mobile-menu">☰</button><div><div class="eyebrow">STOCKLAND ETHIOPIA / WORKSPACE</div><div class="top-title">${esc(navItems.find(x=>x[0]===state.view)?.[1]||'Overview')}</div></div></div><div class="top-right"><span class="status-chip">● Local system</span><span class="location-chip">${esc(user.locationName||'Company-wide')}</span></div></header><section class="content" id="view"></section></main></div>`;
  document.querySelectorAll('[data-view]').forEach(el=>el.addEventListener('click',()=>{state.view=el.dataset.view;document.querySelector('#sidebar').classList.remove('open');shell();renderView();}));
  document.querySelector('#mobile-menu').addEventListener('click',()=>document.querySelector('#sidebar').classList.toggle('open'));
  document.querySelector('#logout').addEventListener('click',async()=>{try{await api('/api/auth/logout',{method:'POST',body:'{}'});}catch{}state.user=null;state.csrf=null;authScreen(false);});
}
async function loadWorkspace(){state.locations=await api('/api/locations');shell();await renderView();}
function pageHead(kicker,title,subtitle,action=''){return `<div class="page-head"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${action}</div>`;}
function emptyRow(cols,message='No records found yet.'){return `<tr><td colspan="${cols}" class="empty">${esc(message)}</td></tr>`;}
function locationOptions(selected='') {return state.locations.map(l=>`<option value="${esc(l.code)}" ${selected===l.code?'selected':''}>${esc(l.name)}</option>`).join('');}
function scopedLocationField(name, defaultCode='GORO_BRANCH') {
  const locked=['branch_manager','cashier','warehouse_manager'].includes(state.user.role);
  if(!locked) return `<div class="field"><label>Location</label><select name="${name}">${locationOptions(defaultCode)}</select></div>`;
  const code=state.user.locationCode || defaultCode;const loc=state.locations.find(x=>x.code===code);
  return `<div class="field"><label>Location</label><input value="${esc(loc?.name||code)}" disabled><input type="hidden" name="${name}" value="${esc(code)}"></div>`;
}
function parseCsvRows(text) {
  const rows=[];let row=[],field='',quoted=false;
  for(let i=0;i<text.length;i++) {const ch=text[i],next=text[i+1];if(quoted){if(ch==='"'&&next==='"'){field+='"';i++;}else if(ch==='"')quoted=false;else field+=ch;}else if(ch==='"')quoted=true;else if(ch===','){row.push(field.trim());field='';}else if(ch==='\n'){row.push(field.trim());if(row.some(x=>x!==''))rows.push(row);row=[];field='';}else if(ch!=='\r')field+=ch;}
  row.push(field.trim());if(row.some(x=>x!==''))rows.push(row);if(quoted)throw new Error('CSV contains an unclosed quoted field.');return rows;
}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows||emptyRow(headers.length)}</tbody></table></div>`;}
async function renderView(){
  const view=document.querySelector('#view');if(!view)return;
  view.innerHTML='<div class="card empty">Loading operational data…</div>';
  try {
    if(state.view==='dashboard') view.innerHTML=await dashboardView();
    else if(state.view==='products') view.innerHTML=await productsView();
    else if(state.view==='inventory') view.innerHTML=await inventoryView();
    else if(state.view==='pos') view.innerHTML=await posView();
    else if(state.view==='imports') view.innerHTML=await importsView();
    else if(state.view==='suppliers') view.innerHTML=await suppliersView();
    else if(state.view==='customers') view.innerHTML=await customersView();
    else if(state.view==='procurement') view.innerHTML=await procurementView();
    else if(state.view==='requisitions') view.innerHTML=await requisitionsView();
    else if(state.view==='reservations') view.innerHTML=await reservationsView();
    else if(state.view==='counts') view.innerHTML=await countsView();
    else if(state.view==='returns') view.innerHTML=await returnsView();
    else if(state.view==='wholesale') view.innerHTML=await wholesaleView();
    else if(state.view==='finance') view.innerHTML=await financeView();
    else if(state.view==='hr') view.innerHTML=await hrView();
    else if(state.view==='closing') view.innerHTML=await closingView();
    else if(state.view==='reports') view.innerHTML=await reportsView();
    else if(state.view==='users') view.innerHTML=await usersView();
    else if(state.view==='audit') view.innerHTML=await auditView();
    bindViewEvents();
  } catch(error){view.innerHTML=`<div class="notice error">${esc(error.message)}</div>`;}
}
async function dashboardView(){
  const d=await api('/api/dashboard');const sales=await api('/api/reports/sales');
  return `${pageHead('COMMAND CENTRE','Operations at a glance','Monitor products, branch stock, today’s sales and import batches.')}
    <div class="grid kpis"><div class="card"><div class="kpi-label">Active products</div><div class="kpi-value">${d.productCount}</div><div class="kpi-note">Garment SKU master</div></div><div class="card"><div class="kpi-label">Stock units</div><div class="kpi-value">${qty(d.stockUnits)}</div><div class="kpi-note">Across permitted locations</div></div><div class="card"><div class="kpi-label">Sales today</div><div class="kpi-value">${money(d.salesToday)}</div><div class="kpi-note">${d.saleCountToday} posted transactions</div></div><div class="card"><div class="kpi-label">Low stock items</div><div class="kpi-value">${d.lowStockCount}</div><div class="kpi-note">Reorder review threshold: 5</div></div></div>
    <div class="grid two-col"><div class="card"><div class="card-head"><h3>Branch overview</h3><span class="tag">Last 30 days</span></div>${table(['Location','Sales','Transactions'],sales.map(r=>`<tr><td><strong>${esc(r.location_name)}</strong></td><td>${money(r.total)}</td><td>${r.sale_count}</td></tr>`).join(''))}</div><div class="card"><div class="card-head"><h3>Operational controls</h3><span class="tag warn">${d.pendingImports} imports pending</span></div><div class="grid" style="gap:12px"><div class="notice">POS import sequence: upload → automatic validation → staging → reconciliation → Branch Manager release → automatic posting.</div><div class="notice warning">An upload is not an approval. Branch Manager release is the final business approval; Owner approval is not inserted afterward.</div><div class="row" style="justify-content:space-between"><span class="small muted">Low-stock alert count</span><strong>${d.lowStockCount}</strong></div><div class="row" style="justify-content:space-between"><span class="small muted">Pending import batches</span><strong>${d.pendingImports}</strong></div></div></div></div>`;
}
