async function closingView(){
  const rows=await api('/api/operations/daily-closings');const canWrite=['owner','admin','branch_manager'].includes(state.user.role);
  return `${pageHead('BRANCH CONTROL','Daily closing','Reconcile cash, card, mobile money and bank totals for each retail branch.')}
    <div class="split"><div class="card"><div class="card-head"><h3>Submit daily close</h3></div>${canWrite?`<form id="closing-form"><div class="form-grid"><div class="field"><label>Branch</label><select name="locationCode">${locationOptions(state.user.locationCode||'GORO_BRANCH')}</select></div><div class="field"><label>Business date</label><input name="businessDate" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Opening cash (ETB)</label><input name="openingCash" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Counted cash (ETB)</label><input name="countedCash" type="number" min="0" step="0.01" value="0"></div><div class="field full"><label>Notes</label><input name="notes"></div></div><div class="actions"><button class="btn">Calculate & submit close</button></div></form>`:''}</div><div class="card"><div class="card-head"><h3>Closing register</h3><span class="tag">${rows.length}</span></div>${table(['Date','Location','Status','Expected cash','Counted cash','Variance','Action'],rows.map(r=>`<tr><td>${esc(r.business_date)}</td><td>${esc(r.location_code)}</td><td>${esc(titleCase(r.status))}</td><td>${money(r.expectedCash)}</td><td>${money(r.countedCash)}</td><td>${money(r.cashVariance)}</td><td>${r.status==='submitted'&&canWrite?`<button class="btn" data-post="/api/operations/daily-closings/${r.id}/close">Close day</button>`:'—'}</td></tr>`).join(''))}</div></div>`;
}
function bindModuleForms(){
  const postForm=async(id,path,transform,message)=>{const form=document.querySelector(id);if(!form)return;form.addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(form));try{await api(path,{method:'POST',body:JSON.stringify(transform?transform(b):b)});toast(message);await renderView();}catch(err){toast(err.message,true);}});};
  postForm('#supplier-form','/api/suppliers',null,'Supplier saved.');
  postForm('#customer-form','/api/customers',null,'Customer saved.');
  postForm('#po-form','/api/procurement/orders',b=>({...b,supplierId:Number(b.supplierId),lines:[{sku:b.sku,qty:Number(b.qty),unitCost:Number(b.unitCost)}]}),'Purchase order created.');
  postForm('#requisition-form','/api/inventory/requisitions',b=>({...b,lines:[{sku:b.sku,qty:Number(b.qty)}]}),'Requisition submitted.');
  postForm('#reservation-form','/api/inventory/reservations',b=>({...b,customerId:b.customerId?Number(b.customerId):null,lines:[{sku:b.sku,qty:Number(b.qty)}]}),'Stock reserved.');
  postForm('#count-form','/api/inventory/counts',b=>({...b,lines:[{sku:b.sku,countedQty:Number(b.countedQty)}]}),'Physical count submitted.');
  document.querySelector('#count-csv-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const file=form.elements.countFile.files[0];if(!file)return;try{const parsed=parseCsvRows(await file.text());if(parsed.length<2)throw new Error('The count worksheet has no data rows.');const headers=parsed.shift().map(x=>x.replace(/^\uFEFF/,'').trim().toLowerCase());const skuCol=headers.indexOf('sku'),qtyCol=headers.indexOf('countedqty');if(skuCol<0||qtyCol<0)throw new Error('Required worksheet headers: sku,countedQty.');const lines=parsed.map((r,i)=>({sku:String(r[skuCol]||'').trim(),countedQty:Number(r[qtyCol])}));if(lines.some(x=>!x.sku||!Number.isFinite(x.countedQty)||x.countedQty<0))throw new Error('Every count row needs an SKU and a valid non-negative quantity.');const result=await api('/api/inventory/counts',{method:'POST',body:JSON.stringify({locationCode:form.elements.locationCode.value,notes:form.elements.notes.value||file.name,lines})});toast(`Count ${result.number} submitted · ${lines.length} SKU rows.`);await renderView();}catch(err){toast(err.message,true);}});
  postForm('#damage-form','/api/inventory/damages',b=>({...b,lines:[{sku:b.sku,qty:Number(b.qty)}]}),'Damage report posted.');
  postForm('#return-form','/api/pos/returns',b=>({...b,lines:[{saleLineId:Number(b.saleLineId),qty:Number(b.qty)}]}),'Sales return posted.');
  postForm('#wholesale-form','/api/wholesale/orders',b=>({...b,customerId:Number(b.customerId),lines:[{sku:b.sku,qty:Number(b.qty)}]}),'Wholesale order created.');
  postForm('#expense-form','/api/finance/expenses',null,'Expense posted to accounting.');
  postForm('#ap-form','/api/finance/ap-bills',b=>({...b,supplierId:Number(b.supplierId)}),'Supplier bill created.');
  postForm('#ar-form','/api/finance/ar-invoices',b=>({...b,customerId:Number(b.customerId)}),'Customer invoice created.');
  postForm('#employee-form','/api/hr/employees',null,'Employee created.');
  postForm('#contract-form','/api/hr/contracts',b=>({...b,employeeId:Number(b.employeeId)}),'Employment contract saved.');
  postForm('#attendance-form','/api/hr/attendance',b=>({...b,employeeId:Number(b.employeeId),hours:Number(b.hours)}),'Attendance saved.');
  postForm('#payroll-form','/api/hr/payroll',b=>({...b,lines:[{employeeId:Number(b.employeeId),basicSalary:Number(b.basicSalary||0),allowance:Number(b.allowance||0),overtime:Number(b.overtime||0),incomeTax:Number(b.incomeTax||0),pension:Number(b.pension||0),otherDeduction:Number(b.otherDeduction||0)}]}),'Payroll draft created.');
  document.querySelector('#payroll-form select[name=employeeId]')?.addEventListener('change',e=>{const amount=e.target.selectedOptions[0]?.dataset.salary||0;const input=document.querySelector('#payroll-form [name=basicSalary]');if(input)input.value=amount;});
  postForm('#closing-form','/api/operations/daily-closings',b=>({...b,openingCash:Number(b.openingCash||0),countedCash:Number(b.countedCash||0)}),'Daily close submitted.');
  document.querySelector('#journal-form')?.addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/finance/journals',{method:'POST',body:JSON.stringify({description:b.description,lines:[{accountCode:b.debitAccountCode,debit:b.amount,credit:0},{accountCode:b.creditAccountCode,debit:0,credit:b.amount}]})});toast('Balanced journal posted.');await renderView();}catch(err){toast(err.message,true);}});
  document.querySelector('#load-sale-lines')?.addEventListener('click',async()=>{const saleId=document.querySelector('#return-sale')?.value;if(!saleId){toast('Choose an original sale first.',true);return;}try{const rows=await api(`/api/pos/sales/${encodeURIComponent(saleId)}/lines`);document.querySelector('#sale-lines-box').innerHTML=table(['Line ID','SKU','Product','Sold qty','Unit price'],rows.map(r=>`<tr><td>${r.id}</td><td>${esc(r.sku)}</td><td>${esc(r.name)}</td><td>${qty(r.qty)}</td><td>${money(r.unitPrice)}</td></tr>`).join(''));}catch(err){toast(err.message,true);}});
  document.querySelectorAll('[data-post]').forEach(el=>el.addEventListener('click',async()=>{const path=el.dataset.post;if(!confirm(`Confirm action: ${path.split('/').pop().replaceAll('-',' ')}?`))return;el.disabled=true;try{await api(path,{method:'POST',body:'{}'});toast('Action completed.');await renderView();}catch(err){toast(err.message,true);el.disabled=false;}}));
  document.querySelectorAll('[data-pay]').forEach(el=>el.addEventListener('click',async()=>{const amount=prompt(`Enter payment amount in ETB (open balance ${el.dataset.balance}).`,el.dataset.balance);if(amount===null)return;const method=prompt('Payment method: CASH, CARD, MOBILE_MONEY or BANK_TRANSFER','BANK_TRANSFER');if(!method)return;try{await api(el.dataset.pay,{method:'POST',body:JSON.stringify({amount:Number(amount),paymentMethod:method})});toast('Payment posted and journal updated.');await renderView();}catch(err){toast(err.message,true);}}));
}

function bindProductEditButtons(){
  document.querySelectorAll('[data-product-edit]').forEach(el=>el.addEventListener('click',async()=>{
    const sku=el.dataset.productEdit;const p=state.products.find(x=>x.sku===sku);if(!p)return;
    const name=prompt('Product name',p.name);if(name===null)return;
    const brand=prompt('Brand',p.brand||'');if(brand===null)return;
    const category=prompt('Category',p.category||'');if(category===null)return;
    const size=prompt('Size',p.size||'');if(size===null)return;
    const color=prompt('Colour',p.color||'');if(color===null)return;
    const barcode=prompt('Barcode / GTIN',p.barcode||'');if(barcode===null)return;
    const cost=prompt('Cost price ETB',p.cost);if(cost===null)return;
    const retailPrice=prompt('Retail price ETB',p.retailPrice);if(retailPrice===null)return;
    const wholesalePrice=prompt('Wholesale price ETB',p.wholesalePrice);if(wholesalePrice===null)return;
    try{await api(`/api/products/${encodeURIComponent(sku)}`,{method:'PATCH',body:JSON.stringify({name,brand,category,size,color,barcode,cost:Number(cost),retailPrice:Number(retailPrice),wholesalePrice:Number(wholesalePrice)})});toast('Product variant updated.');await renderView();}catch(err){toast(err.message,true);}
  }));
}

function bindViewEvents(){
  document.querySelector('#product-form')?.addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/products',{method:'POST',body:JSON.stringify(b)});toast('Product SKU created.');await renderView();}catch(err){toast(err.message,true);}});
  document.querySelector('#product-search')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();const p=state.products.filter(x=>[x.sku,x.name,x.brand,x.category].some(v=>String(v||'').toLowerCase().includes(q)));document.querySelector('#product-table').innerHTML=productTable(p,['owner','admin','warehouse_manager'].includes(state.user.role));bindProductEditButtons();});
  document.querySelector('#receipt-form')?.addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/inventory/receipts',{method:'POST',body:JSON.stringify(b)});toast('Goods receipt posted to the stock ledger.');await renderView();}catch(err){toast(err.message,true);}});
  document.querySelector('#transfer-form')?.addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/inventory/transfers',{method:'POST',body:JSON.stringify(b)});toast('Transfer posted atomically.');await renderView();}catch(err){toast(err.message,true);}});
  document.querySelector('#sale-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const b=Object.fromEntries(new FormData(form));b.lines=[{sku:b.sku,qty:Number(b.qty)}];delete b.sku;delete b.qty;const button=form.querySelector('button');const idemKey=form.dataset.idempotencyKey||(form.dataset.idempotencyKey=crypto.randomUUID());button.disabled=true;try{const result=await api('/api/pos/sales',{method:'POST',headers:{'Idempotency-Key':idemKey},body:JSON.stringify(b)});delete form.dataset.idempotencyKey;toast(`Sale posted · ${money(result.total)}${result.duplicate?' · existing transaction recovered':''}`);await renderView();}catch(err){toast(err.message,true);button.disabled=false;}});
  document.querySelector('#import-form')?.addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));const button=e.currentTarget.querySelector('button');button.disabled=true;try{const result=await api('/api/pos/imports',{method:'POST',body:JSON.stringify(b)});toast(`Batch #${result.batchId} · ${result.status} · ${result.validRows} valid · ${result.invalidRows} rejected · variance ${money(result.variance)}`);await renderView();await showBatch(result.batchId);}catch(err){toast(err.message,true);button.disabled=false;}});
  document.querySelectorAll('[data-batch]').forEach(el=>el.addEventListener('click',()=>showBatch(el.dataset.batch)));
  document.querySelector('#user-form')?.addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/users',{method:'POST',body:JSON.stringify(b)});toast('User account created.');await renderView();}catch(err){toast(err.message,true);}});
  bindProductEditButtons();
  document.querySelectorAll('[data-user-toggle]').forEach(el=>el.addEventListener('click',async()=>{const active=el.dataset.active==='1';const label=active?'activate':'deactivate';if(!confirm(`Confirm ${label} this account?`))return;try{await api(`/api/users/${el.dataset.userToggle}`,{method:'PATCH',body:JSON.stringify({active})});toast(`User account ${active?'activated':'deactivated'}.`);await renderView();}catch(err){toast(err.message,true);}}));
  document.querySelectorAll('[data-user-edit]').forEach(el=>el.addEventListener('click',async()=>{const userId=Number(el.dataset.userEdit);const row=el.closest('tr');const currentName=row.children[0].innerText.trim();const name=prompt('Full name',currentName);if(name===null)return;const role=prompt('Role: admin, branch_manager, warehouse_manager, cashier, accountant, auditor',row.children[2].innerText.toLowerCase().replaceAll(' ','_'));if(role===null)return;const currentLoc=state.locations.find(x=>x.name===row.children[3].innerText)?.code||'';const location=prompt(`Location code (${state.locations.map(x=>x.code).join(', ')}); leave blank for company-wide`,currentLoc);if(location===null)return;const password=prompt('New password (leave blank to keep current password)','');try{await api(`/api/users/${userId}`,{method:'PATCH',body:JSON.stringify({fullName:name,role:role.trim(),locationCode:location.trim(),...(password?{password}: {})})});toast('User profile updated.');await renderView();}catch(err){toast(err.message,true);}}));
  bindModuleForms();
}
async function showBatch(id){
  const target=document.querySelector('#batch-detail');if(!target)return;
  try{
    const b=await api(`/api/pos/imports/${id}`);const canRelease=state.user.role==='branch_manager'&&state.user.locationId===b.location_id&&b.status==='staged'&&b.invalid_rows===0;
    target.innerHTML=`<div class="card"><div class="card-head"><div><div class="eyebrow">IMPORT BATCH #${b.id}</div><h3 style="font:700 16px Manrope;margin:4px 0">${esc(b.source_name)}</h3><p class="hint">${esc(b.location_name)} · ${esc(titleCase(b.status))}</p></div>${canRelease?'<button class="btn" id="release-batch">Branch Manager release & post</button>':''}</div><div class="grid kpis"><div><div class="kpi-label">Rows</div><strong>${b.row_count}</strong></div><div><div class="kpi-label">Valid / rejected</div><strong>${b.valid_rows} / ${b.invalid_rows}</strong></div><div><div class="kpi-label">Expected total</div><strong>${money(b.expectedTotal)}</strong></div><div><div class="kpi-label">Reconciled total</div><strong>${money(b.reconciledTotal)}</strong></div></div>${b.last_error?`<div class="notice error">${esc(b.last_error)}</div>`:''}${b.status==='posted'?`<div class="notice">Released and automatically posted at ${date(b.posted_at)}. Releaser user ID: ${b.released_by}.</div>`:''}${table(['Row','External sale','SKU','Qty','Unit price','Payment','Status / errors'],b.rows.map(r=>`<tr><td>${r.row_number}</td><td>${esc(r.external_sale_id)}</td><td><span class="code">${esc(r.sku)}</span></td><td>${qty(r.qty)}</td><td>${money(r.unitPrice)}</td><td>${esc(r.payment_method)}</td><td>${r.row_status==='valid'?'<span class="tag">Valid</span>':`<span class="tag bad">${esc(r.errors.join('; '))}</span>`}</td></tr>`).join('')||emptyRow(7))}</div>`;
    document.querySelector('#release-batch')?.addEventListener('click',async()=>{if(!confirm('Release this batch as the final Branch Manager approval and automatically post all sales and stock movements?'))return;const btn=document.querySelector('#release-batch');btn.disabled=true;try{const result=await api(`/api/pos/imports/${id}/release`,{method:'POST',body:'{}'});toast(`Batch #${id} released and auto-posted · ${result.salesPosted} sales.`);await renderView();await showBatch(id);}catch(err){toast(err.message,true);btn.disabled=false;}});
  }catch(err){target.innerHTML=`<div class="notice error">${esc(err.message)}</div>`;}
}
async function start(){
  try{if('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(()=>{});const session=await api('/api/auth/session');state.user=session.user;state.csrf=session.csrfToken;if(session.setupRequired&&!state.user){authScreen(true);return;}if(!state.user){authScreen(false);return;}await loadWorkspace();}
  catch(error){app.innerHTML=`<div class="auth-panel"><div class="auth-card"><h2>Service unavailable</h2><p class="subtle">${esc(error.message)} Check that the local server is running and try again.</p></div></div>`;}
}
start();
